using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
public static class JewelUiValidate {
 public static string Run() {
 if(EditorUtility.scriptCompilationFailed)throw new Exception("Compile failed");
 var rows=UnityEngine.Object.FindObjectsByType<PinkJewelIconRow>(FindObjectsInactive.Include);
 if(rows.Length!=2)throw new Exception("Expected HUD and result rows");
 Sprite shared=null;string output="";
 foreach(var row in rows) {
 var settings=new SerializedObject(row);
 var collected=(Sprite)settings.FindProperty("collectedIcon").objectReferenceValue;
 var empty=(Sprite)settings.FindProperty("emptyIcon").objectReferenceValue;
 if(collected.name!="JewelCollected" || empty.name!="JewelEmpty" || AssetDatabase.GetAssetPath(collected)!="Assets/Art/PinkJewel/JewelUI.png")throw new Exception("Incorrect supplied sprites");
 if(shared!=null && shared!=collected)throw new Exception("Rows do not share the same sprite");shared=collected;
 for(int i=0;i<3;i++) {
 var image=(UnityEngine.UI.Image)settings.FindProperty("icons").GetArrayElementAtIndex(i).objectReferenceValue;
 if(image.sprite!=empty || image.rectTransform.sizeDelta!=new Vector2(54f,87f) || image.rectTransform.anchoredPosition!=new Vector2(27f+i*60f,0f))throw new Exception("Incorrect icon layout");
 }
 var rect=(RectTransform)row.transform;
 if(row.name.StartsWith("PinkJewelHUD",StringComparison.Ordinal) && (rect.anchorMin!=Vector2.zero || rect.pivot!=new Vector2(0,1) || rect.anchoredPosition!=new Vector2(24,-50)))throw new Exception("HUD not left aligned");
 output+=row.name+" rect="+rect.rect+" anchors="+rect.anchorMin+" position="+rect.anchoredPosition+"\n";
 }
 var goal=UnityEngine.Object.FindAnyObjectByType<GoalMenuController>(FindObjectsInactive.Include);
 if(goal.transform.Find("CRTPresentation/PhosphorUI/SafeArea/Subtitle").GetComponent<TMPro.TMP_Text>().text.Length!=0)throw new Exception("Crystal subtitle still visible");
 return output+"compileFailed=False; same supplied sprites; original pixel geometry retained; icons=54x87; gaps=6; subtitle empty; playing="+EditorApplication.isPlaying+" sceneDirty="+UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty;
 }
}
